"""Read-only exact host/renderer/hook lifetime proof after native renderer loss."""
from pathlib import Path
import json,subprocess,time
out=Path(__file__).resolve().parent;f=json.loads((out/'native-fixture.json').read_text());proof=json.loads((out/'native-running-proof.json').read_text());root=Path(f['root']);events=[json.loads(l)for l in Path(f['state']+'/native-acceptance-events.jsonl').read_text().splitlines()];kills=[e for e in events if e['event']=='renderer_kill_requested'];assert len(kills)==1
renderer=kills[0]['detail']['pid'];assert kills[0]['detail']['host_pid']==proof['host_pid'] and renderer!=proof['host_pid'];assert any(e['event']=='renderer_kill_result' and e['detail']=={'pid':renderer,'success':True}for e in events);assert any(e['event']=='main_renderer_reset'for e in events)
host=json.loads((out/'initial-host-process.json').read_text());h=subprocess.check_output(['ps','-p',str(host['pid']),'-o','pid=,ppid=,pgid=,stat=,args='],text=True);assert host['executable']in h and f['state']in h
pids=[renderer,proof['hook_pid'],proof['child_pid']];p=subprocess.run(['ps','-p',','.join(map(str,pids)),'-o','pid=,ppid=,pgid=,stat=,args='],capture_output=True,text=True);assert p.returncode==1 and not p.stdout.strip();now=time.time_ns();elapsed=(now-proof['hook_started_mtime_ns'])/1e6;assert elapsed<45000 and not(root/'hook-finished').exists()
(out/'native-process-recovery.json').write_text(json.dumps({'host_survived_same_pid':host['pid'],'host_process':h,'killed_renderer_pid':renderer,'original_renderer_hook_child_absent':pids,'ps_returncode':p.returncode,'ps_stdout':p.stdout,'observed_at_ns':now,'elapsed_since_hook_start_ms':elapsed,'cleanup_before_natural_finish':True,'external_host_hook_or_child_signal':False},indent=2)+'\n');print('Same host alive; exact old renderer/hook/child absent before natural completion: '+str(elapsed)+' ms')
